
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m11_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m11_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.705639232001121e-01, -3.595707039320898e-01, -3.441273264307494e-01, -3.226853163355772e-01, -2.933881178305822e-01, -2.539341601067568e-01, -1.996936062306706e-01, -1.139983177420638e-01, 4.325240296166002e-02, 2.177988769574009e-01, 1.747825889351659e-01, -5.526850751351410e-02, -4.854962482220927e-02, -3.169172973801829e-02, 5.799625219875052e-02, 7.243280616308151e-02, -2.438582687381817e-02, -3.272501640342953e-02, -1.012266221705271e-02, -1.448664774146135e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


